// Domenia 1 functions still to port, grouped by Domenia 2 page. Generated from dev/web/PARITE.json
// (WPF control inventory): s = section ( = main screen), f = [title, detail]. Regenerate rather than edit by hand.
export const PARITE = {"rechercher":[{"s":"","f":[["Actualiser l’arbre","Recharge les branches de l’arbre. Le texte de recherche et le filtre OU courant sont conservés."],["Options de l’arbre des OU","Ouvre les options de l’arbre : inclure les sous-OU, tout le domaine, épingler l’OU choisie et voir son chemin LDAP. Ouvrir ce menu ne lance aucune lecture."],["Inclure les sous-OU dans les résultats","Coché : recherche dans la branche et ses sous-branches. Décoché : seulement ses enfants directs. Les trois commandes Données de l’OU actualisent toujours toute l’OU et ses sous-OU."],["Épingler ou retirer l’OU choisie","Ajoute l’OU choisie aux favoris en haut de l’arbre, ou l’en retire. Préférence locale : rien n’est lu ni modifié dans l’annuaire."],["Chemin complet de l’OU","Déplie le DN exact utilisé par la recherche. Cela ne change pas le périmètre et ne lance aucune requête."],["OU utilisée pour la recherche","Chemin LDAP complet de la branche sélectionnée. Cette racine est utilisée par la requête AD, pas seulement pour masquer des lignes."],["Copier le chemin LDAP","Copie seulement le DN de l’OU sélectionnée. Ne modifie pas le filtre et ne contacte pas l’annuaire."],["OU mémorisée","Distingue une OU absente sous son parent relu d’une lecture non aboutie ; un délai n’est jamais présenté comme une absence."],["Relire l’OU mémorisée","Relance une seule fois la restauration de l’OU mémorisée dans l’arbre. Aucun autre périmètre n’est appliqué."],["Choisir une autre OU","Ferme l’avertissement : choisissez une OU dans l’arbre. Le périmètre actuel n’est pas modifié."],["Filtrer les OU","Filtre local de l’arbre sur le nom des branches déjà affichées. Aucune lecture de l’annuaire ; une branche jamais dépliée n’est pas parcourue."],["Actualiser l’OU",""],["Données de l’OU",""],["Périmètre des données de l’OU","Ces commandes utilisent l’OU choisie dans l’arbre de Rechercher et toutes ses sous-OU. Elles ne sont pas limitées par les résultats affichés, leurs filtres ou la case Inclure les sous-OU. Sans OU explicite, choisissez d’abord une branche."],["Mettre à jour la base locale de l’OU","Relit Active Directory pour l’OU choisie dans l’arbre de Rechercher et toutes ses sous-OU, y compris pendant une recherche globale, puis enregistre la copie locale, après une sauvegarde vérifiée de la base. Aucun ping ni WMI ; aucun…"],["Actualiser les postes de l’OU par ping et WMI","Relit le ping, la console, l’inventaire léger et les sondes WMI des widgets Général/Poste sur les comptes ordinateur actifs recensés dans l’OU et ses sous-OU. L’OU est celle de l’arbre de Rechercher, même pendant une recherche globale.…"],["Mettre à jour la base locale puis les postes","Relit AD pour l’OU et ses sous-OU. L’OU est celle de l’arbre de Rechercher, même pendant une recherche globale. Après lecture complète et enregistrement confirmé, prépare le ping, la console, l’inventaire léger et les sondes des widgets…"],["Arrêter l’actualisation de l’OU","Empêche les nouveaux départs et le lancement de la phase suivante. Conserve les données déjà enregistrées ; attendez le bilan de l’opération avant de fermer Domenia."],["Progression de l’actualisation de l’OU","Distingue la lecture AD, l’enregistrement local et le relevé des postes. Une mesure en échec reste signalée avec sa date ; une erreur ou un arrêt empêche la phase suivante."],["Arbre pret.",""],["Arbre des OU et conteneurs","Développez les sous-OU ou cliquez une branche pour afficher son contenu. Le texte de la recherche globale reste conservé mais ne filtre pas cette navigation."],["Lignes affichées","Nombre de lignes affichées dans la liste, après le filtre de la liste. Le compteur détaillé, au-dessus des résultats, indique les lignes chargées et la limite."],["Options de requête","Afficher ou replier les options : recherche de modèle, favoris, source et état des résultats."],["Périmètre des requêtes","Les requêtes utilisent l’OU choisie dans l’arbre de Recherche et sa profondeur. Ce choix ne lance aucune lecture."],["Dans : tout le domaine | Sous-OU incluses",""],["Lecture de la saisie","Explique comment le texte du bandeau est compris : jetons explicites (utilisateur:, poste:, groupe:, mail:), identifiant collé reconnu ou préfixe inconnu cherché comme texte. Aucun filtre caché, aucune requête."],["Type d’objet","Type d’objet lu dans l’OU choisie : tous les types, utilisateurs, machines, groupes, ou OU et conteneurs. Le filtre fait partie de la requête AD."],["Présence réseau","Présence réseau mémorisée des postes de la liste : « Toute présence » les montre tous. « Sans réponse au ping » ne prouve pas qu’un poste est éteint. Aucun ping collectif ; le choix n’est pas gardé d’une session à l’autre."],["Unité de la limite","La limite de la liste est un nombre de lignes lues dans l’annuaire."],["Lignes max","Nombre maximum de lignes lues dans l’annuaire pour cette liste, 20 000 au plus. « Charger la suite » lit les lignes suivantes sans changer ce nombre."],["Rechercher dans les requêtes","Filtrer les noms et descriptions de la bibliothèque, sans exécuter de requête."],["Requêtes favorites","Afficher uniquement les requêtes épinglées. Aucun résultat ni relevé n’est modifié."],["Requête à exécuter","Choisir une requête Annuaire ou Données locales, puis Exécuter. La source, le type d’objet et l’OU sont indiqués sous la liste. Le choix seul ne lance rien."],["Exécuter la requête","Exécuter la requête choisie dans l’OU de Recherche, avec ou sans sous-OU selon le choix affiché. Les anciens filtres masquants sont retirés ; aucune collecte distante automatique."],["Épingler la requête","Ajouter ou retirer la requête sélectionnée des favoris personnels."],["Modifier dans l’atelier","Ouvrir Outils, Atelier de requêtes pour créer ou modifier une recette. Une lecture Annuaire reste identifiée séparément des requêtes sur données locales."],["Choisissez une requête pour voir sa source et son périmètre.",""],["Aucune requête appliquée aux résultats.",""],["Résultats de la requête locale","Choisir les postes correspondants, inconnus ou non correspondants. Une information absente ou périmée reste inconnue."],["Effacer la requête appliquée","Retirer le filtre de requête des résultats affichés."],["Terme masqué de l’OU","Champ masqué conservé pour compatibilité ; il reste vide. Pour réduire la liste affichée, utilisez « Filtrer la liste », sans requête AD."],["Ancien filtre de type","Ancien filtre de type, masqué : le type se choisit dans la liste « Tous les types » au-dessus des résultats."],["Ancienne limite de branche","Ancienne limite de branche, masquée : la limite se règle dans « lignes max » au-dessus des résultats."],["Vider la recherche (commande masquée)","Commande masquée, remplacée par « Effacer la recherche » : vide le texte et les résultats sans modifier l’OU choisie."],["Actualiser les résultats","Relance la lecture du mode affiché, avec son périmètre et ses filtres. Pour actualiser les données de toute l’OU, utilisez Objets AD, Ping ou WMI sous l’arbre ; ces commandes incluent toujours les sous-OU."],["Exporter CSV","Exporte au format CSV la portée choisie à côté des résultats : la liste affichée après les filtres, ou seulement les lignes sélectionnées. Le message final dit ce qui est exclu."],["Effacer la recherche","Efface le texte et les résultats sans modifier l’OU sélectionnée. Tout le domaine retire le filtre OU."],["Autres actions de la liste","Autres actions de la liste : actualiser, exporter en CSV et choisir les colonnes affichées. Aucune lecture ne part à l’ouverture du menu."],["Charger la suite","Disponible quand la liste est limitée : lit seulement les lignes suivantes de la même recherche, triées par nom, sans relire les lignes déjà chargées. Plafond de sécurité : 20 000 lignes."],["Charger jusqu’à 1 000","Porte la liste à 1 000 lignes en une fois (puis 5 000, puis 20 000) : lit seulement les lignes manquantes, sans relire celles déjà chargées."],["0 objet",""],["Actualiser la liste de l’historique","Relance dans l’annuaire la recherche de cette liste, avec son périmètre, sa vue et ses filtres. Aucun ping ni relevé des postes."],["Chercher aussi les noms qui contiennent ce texte","Proposé quand la barre du haut trouve peu de noms ou aucun : relance la même recherche (même périmètre, même type, même limite) sur les noms qui contiennent le texte, pas seulement ceux qui commencent par lui. Plus lent ; rien n’est lu…"],["Chercher dans le DNS","Proposé quand aucune adresse IP relevée ne correspond : lance une résolution DNS inverse du nom du poste, puis cherche ce nom dans l’annuaire comme une recherche normale. Une requête réseau part seulement avec ce clic ; un poste peut…"],["Actions, filtres et vues",""],["Filtre local : affine seulement les lignes déjà chargées.",""],["Filtrer la liste","Filtre de la liste : garde les lignes déjà chargées dont le nom, le login, le type, la présence ou l’association contient le texte. Plusieurs mots se combinent. Aucune requête AD ; une nouvelle recherche le remet à zéro."],["Effacer le filtre local","Réaffiche les lignes déjà chargées, en conservant le filtre OU, la présence et le texte de recherche AD."],["Vérifier au clic","Décochée : un clic sur un poste précharge seulement sa fiche AD, sans aucun appel au poste. Cochée : le clic envoie aussi un seul ping au poste sélectionné. Revérifier ce poste reste le geste manuel. Jamais de sondage collectif."],["Vérifier aussi l’utilisateur connecté","Avec Vérifier au clic : lit aussi l’utilisateur connecté à la console du poste cliqué (CIM). Revérifier ce poste le lit toujours. Les sessions RDP ne sont pas recensées."],["Revérifier ce poste","Relance un ping unique et la lecture utilisateur sur le poste sélectionné. Si le compte est refusé ou CIM désactivé, seul le ping reste disponible. Aucun balayage."],["Choisir la vérification de la liste","Choisir la vérification de la liste : Qui répond ? (ping), Qui est connecté ? (ping et utilisateur console) ou Matériel et widgets (relevé WMI léger). Le dernier choix devient l’action du bouton pour cette session."],["Revérifier la liste en arrière-plan","Présent seulement si l’administrateur l’a activé : relit dans l’annuaire les objets listés, par petits lots, tant que la page est affichée. Décochez pour l’arrêter pendant cette session."],["Avancement du relevé de la liste","Avancement du relevé de la liste en cours."],["Aperçu de lecture","Une ligne de 20 unités : type, nom, état de lecture. La souris donne le détail."],["Lignes sélectionnées","Nombre de lignes sélectionnées. Ctrl ou Maj et clic pour composer la sélection."],["Pinger les postes sélectionnés","Pinge les seuls postes sélectionnés, après confirmation avec leur nombre. Aucune lecture de session."],["Utilisateur connecté des postes sélectionnés","Ping puis utilisateur connecté à la console des seuls postes sélectionnés, après confirmation avec leur nombre."],["Copier la sélection pour un ticket","Copie une ligne lisible par objet sélectionné pour un ticket : type, nom, compte, présence, utilisateur console et OU. Sans GUID ni champ interne."],["Exporter la sélection","Exporte les lignes sélectionnées au format CSV, avec les colonnes visibles."],["Un clic : fiche AD seulement, sans ping · Double-clic : ouvrir la fiche · Aucune sonde de liste",""],["Avancement du relevé","Avancement du relevé de la liste : postes traités, joignables, puis en ligne, sans réponse et en erreur. Le détail complet est écrit dans le journal."],["Afficher les postes en ligne","Affiche seulement les postes qui ont répondu au ping. Un second clic retire le filtre. Filtre local, sans appel réseau."],["Afficher les postes sans réponse","Affiche seulement les postes sans réponse au ping : éteint, hors réseau ou ICMP filtré, sans preuve d’arrêt. Un second clic retire le filtre."],["Afficher les postes en erreur de ping","Affiche seulement les postes dont le ping n’a pas abouti (résolution DNS, erreur réseau ou lecture interrompue). Un second clic retire le filtre."],["Vue personnelle","Vues personnelles de ce domaine : OU, profondeur, type, présence, filtre local, limite, colonnes et tri. Choisir une vue ne lance rien ; Ouvrir l’applique sans appel réseau."],["Enregistrer la vue","Mémorise sous un nom l’OU, la profondeur, les filtres, les colonnes (ordre et largeur) et le tri. Les résultats et les mots de passe ne sont pas enregistrés."],["Ouvrir la vue","Applique la vue choisie sans appel réseau. La liste reste vide jusqu’à une lecture que vous lancez."],["Retirer la vue","Retire la vue choisie de ce domaine. Annuler la restaure tant que les vues ne changent pas."],["Annuler le retrait de vue","Annule le dernier retrait de vue personnelle."],["Portée de l’export et des relevés","Portée de l’export CSV et de « Vérifier la liste » : la liste affichée après les filtres, ou seulement les lignes sélectionnées. La barre d’une sélection multiple agit toujours sur les lignes sélectionnées."],["Comparer les postes","Compare côte à côte deux à huit postes sélectionnés, depuis la base locale. Chaque valeur garde sa date ; aucune collecte."],["Aperçu local","Affiche ou masque l’aperçu latéral de la ligne courante, lu dans la base locale. La sélection de travail est conservée ; aucune collecte."],["Combinaison des critères","Combinaison des critères et nombre de lignes affichées. Les critères de la liste chargée ne lisent rien au-delà des lignes déjà chargées."],["Lignes traitées par l’export et les relevés","Lignes que l’export et les relevés vont traiter, avec ce qui est exclu et ce que l’on sait de la complétude de la liste."],["Qui répond ?",""],["Qui est connecté ?",""],["Matériel et widgets",""],["Complet : correctifs",""],["Réessayer les sans adresse",""],["Arrêter ou vérifier la liste","Vérifie les postes de la portée choisie à côté des résultats : la liste affichée après vos filtres, ou seulement les lignes sélectionnées. Sans choix dans cette session, ouvre les trois vérifications ; ensuite, relance la dernière…"],["Résultats : sélection et ouverture explicite","Un clic précharge la fiche AD sans changer de page ; pour un poste, un ping seulement si Vérifier au clic est coché. Double-clic ou Entrée ouvre la fiche en réutilisant sa lecture. Clic droit : actions de la ligne, sans écriture. Aucun…"],["{Binding PresenceAge}",""],["État de la liste de résultats","Pourquoi la liste est vide : rien interrogé, lecture en cours, aucun résultat, filtre local, lecture refusée, partielle ou sans source. Jamais une preuve d’absence dans l’annuaire."],["Explication de la liste vide","Ce qui a été lu, dans quel périmètre, et ce que la liste vide ne permet pas de conclure."],["Prochaine action proposée","Prochaine action proposée pour cette liste vide. Rien ne part tout seul : une lecture ne commence qu’avec ce clic."],["Fermer l’aperçu","Ferme l’aperçu. La sélection et la liste sont conservées."],["Objet consulté dans l’aperçu","Objet consulté et révision de la base locale lue."],["Valeurs enregistrées de l’objet","Valeurs enregistrées de l’objet consulté, chacune avec sa date. « Non lu » signifie que la base locale ne contient pas cette information."]]}],"fiche":[{"s":"","f":[["Aucune fiche ouverte",""],["Rechercher une fiche","Nom, identifiant, adresse mail ou poste. Entrée lance la recherche dans tout le domaine ; la saisie seule ne lit rien."],["Dernières fiches consultées","Fiches ouvertes récemment, gardées dans la mémoire locale de ce poste. Un clic recopie le nom ; Entrée lance la recherche."],["Aucune fiche consultée récemment.",""],["Sélectionnez un objet dans Rechercher.",""],["Réessayer la lecture AD","Relit uniquement cette fiche AD, sans ping, sonde ni écriture."],["Vues de la fiche","Affiche les informations et actions adaptées au type d’objet. Le mode Expert ajoute les vues techniques."]]},{"s":"Résumé","f":[["Type de l’objet","Utilisateur, machine, groupe ou conteneur : le type détermine les vues disponibles."],["Nom de l’objet","Nom de l’objet chargé depuis l’annuaire. Ce champ ne modifie pas l’objet."],["Classe",""],["Classe Active Directory","Classe technique de l’objet lue dans l’annuaire. Cette information est en lecture seule."],["GUID",""],["Identifiant unique","Identifiant GUID de l’objet AD. Il distingue les objets même lorsqu’ils portent un nom identique."],["Date de création","Date de création retournée par l’annuaire pour cet objet."],["Dernière modification","Date de modification retournée par l’annuaire. Elle ne décrit pas à elle seule ce qui a changé."],["Emplacement dans l’annuaire","Chemin complet de l’objet dans Active Directory, également appelé DN. Lecture seule ici."],["Presence","Poste : joignable ou non. Utilisateur : état du poste qui lui est associé."],["Cible testee","Machine effectivement interrogee."],["Copier le resume","Copie les informations principales de l’objet."],["Ouvrir le parent","Affiche le contenu du conteneur qui heberge cet objet."],["Relire l’objet depuis l’annuaire","Relit cet objet sur le contrôleur en écartant les lectures gardées en mémoire pour lui seul. Les autres fiches et la liste restent inchangées ; rien n’est modifié dans l’annuaire."],["Plus d’actions sur l’objet","Ouvre les actions lourdes de l’objet : la suppression y est rangée, séparée des boutons de lecture."]]},{"s":"Utilisateur","f":[["État du compte relevé sur le contrôleur","État relevé à la lecture de la fiche : verrouillage, échéance du mot de passe, échecs de connexion. Le bandeau ne parait que quand le contrôleur a quelque chose à signaler."],["Limites de l’état du compte","Rappelle ce que la valeur affichée ne prouve pas : un compteur d’échecs n’est pas répliqué, une échéance calculée ne remplace pas la stratégie."],["Déverrouiller maintenant le compte verrouillé","Efface l’horodatage de verrouillage sur le contrôleur interrogé, avec la valeur avant et la valeur après."],["Lire les verrouillages du compte","Lit les événements 4740 de ce compte sur l’émulateur PDC (7 derniers jours) et les rapproche des refus d’authentification de Domenia."],["Verrouillages journalisés du compte","Verrouillages relevés dans le journal Sécurité, poste à l’origine et refus de Domenia juste avant. Le rapprochement horaire est une piste, pas une preuve."],["Prenom","Prénom de l’utilisateur."],["Nom","Nom de famille."],["Nom affiche","Nom affiche dans les annuaires et la messagerie."],["Identifiant court","Nom de compte utilisé avec la forme DOMAINE\\identifiant."],["Identifiant de connexion complet","Nom de connexion de forme utilisateur@domaine. Il peut différer de l’adresse mail."],["Mail","Adresse de messagerie principale."],["Telephone","Telephone professionnel."],["Bureau","Bureau ou site d’affectation."],["Description","Description libre affichee dans la console Active Directory."],["Fonction","Intitule de poste."],["Service","Service ou direction."],["Societe","Societe ou entite de rattachement."],["Responsable","Nom du responsable hiérarchique, lu dans l’annuaire. Le chemin complet reste interne : il ne se tape plus."],["Choisir le responsable","Ouvre le sélecteur d’utilisateurs du domaine : la recherche se lance sur Entrée ou sur le bouton, jamais pendant la frappe. Le choix reste local, aucune écriture n’est lancée par ce clic."],["Ouvrir le responsable","Ouvre la fiche de l’utilisateur choisi comme responsable. Aucune écriture, aucune sonde de poste lancée par ce clic."],["Retirer le responsable","Retirer le responsable affiché de la fiche. L’effacement de la valeur dans l’annuaire ne se fait qu’à l’enregistrement."],["Présence du poste associé","État de joignabilité connu du poste associé. Cela ne prouve pas que l’utilisateur est actuellement connecté."],["État du compte","État affiché à partir des données AD chargées. Utilisez une relecture pour contrôler une modification récente."],["Dernière connexion connue","Date connue dans les données retournées. Ce n’est pas un indicateur de session en temps réel."],["Date du dernier changement du mot de passe","Date du dernier changement de mot de passe, lue dans pwdLastSet. Une valeur à zéro s’affiche « Jamais » et signifie qu’un changement est exigé à la prochaine ouverture de session. Le champ est en lecture seule : il n’affiche aucun mot…"],["Expiration du compte","Date d’expiration du compte retournée dans la fiche. Ne pas confondre avec l’expiration du mot de passe."],["Options du compte AD","Options techniques du compte dans userAccountControl. Ce champ ne concerne pas l’élévation UAC de Windows."],["Postes associés","Sélectionnez un poste associé à l’utilisateur. Une association peut provenir du cache ou d’une détection et ne prouve pas une session active."],["Ouvrir le poste","Ouvre la fiche du poste associé."],["Aucun poste associé.",""],["Enregistrer","Enregistre les modifications de la fiche dans Active Directory."],["Modifier la fiche","Déverrouille les champs de la fiche pour les modifier. Le crayon n’écrit rien : il ouvre seulement la saisie, et « Enregistrer » reste seul à décider de ce qui part dans l’annuaire."],["Annuler les modifications","Rejette les modifications non enregistrées : chaque champ reprend la valeur lue dans l’annuaire et la fiche se verrouille de nouveau."],["État des modifications de la fiche","Dit ce que la fiche a en modification, et le signale quand une valeur non enregistrée a été abandonnée en changeant d’objet. Rien n’est parti sans que la page le dise."],["Activité de connexion du compte","Activité de connexion de l’objet : date approximative répliquée (lastLogonTimestamp) et, après lecture, la date exacte connue de chaque contrôleur avec sa couverture."],["Lire la dernière connexion sur chaque contrôleur","Lit, pour cet objet seulement, la date exacte de dernière connexion (lastLogon) sur chaque contrôleur du domaine, avec la liste des contrôleurs lus et non lus. Lecture seule ; aucun contrôleur n’est plus interrogé après 75 secondes."]]},{"s":"Coordonnées","f":[["Rue","Numéro et nom de rue."],["Ville","Ville."],["Departement ou region","Département, région ou état."],["Code postal","Code postal."],["Pays","Nom complet du pays."],["Domicile","Telephone personnel."],["Mobile","Telephone mobile."],["Telecopie","Numéro de télécopie."],["Telephone IP","Numéro de téléphone sur IP."],["Page web","Adresse de la page web personnelle."],["Matricule","Matricule interne de l’employé."],["Chemin du profil","Chemin réseau du profil itinérant. Vide : profil local."],["Script de connexion","Script exécuté à l’ouverture de session."],["Dossier de base","Dossier personnel de l’utilisateur sur le réseau."],["Lecteur de base","Lettre du lecteur réseau, par exemple H:"],["Postes autorises","Postes depuis lesquels l’utilisateur peut ouvrir une session, séparés par des virgules. Vide : aucune restriction."],["Enregistrer","Enregistre l’adresse, la téléphonie, le profil et les postes autorisés."]]},{"s":"Compte","f":[["Déverrouiller le compte","Deverrouille le compte."],["Activer","Reactive le compte."],["Desactiver","Désactive le compte. L’utilisateur ne pourra plus ouvrir de session."],["Mot de passe","Saisie protégée : l’aide contextuelle ne lit jamais la valeur de ce champ."],["Afficher le mot de passe","Afficher le mot de passe."],["Deverrouiller ensuite","Déverrouille aussi le compte après la réinitialisation."],["Afficher la confirmation","Afficher la confirmation."],["Changement obligatoire","L’utilisateur devra choisir son propre mot de passe à la prochaine ouverture de session."],["Générer un mot de passe temporaire","Génère un mot de passe temporaire, le place dans les deux champs et le copie dans le presse-papiers, qui s’efface à l’échéance réglée. Aucune écriture n’est lancée par ce clic."],["Carte à puce","Exige une carte à puce pour ouvrir une session."],["Non delegable","Interdit la délégation de ce compte. Recommandé pour les comptes à privilèges."],["Appliquer","Enregistre les options de compte cochées ci-dessus."],["Options de sécurité avancées","Six options qui affaiblissent la sécurité du compte. Elles ne sont proposées qu’en profil Expert et chaque changement passe par une confirmation qui affiche la valeur avant et la valeur après."],["Avertissement de sécurité","Le moteur refuse d’enregistrer l’une de ces options sans une confirmation qui montre la valeur avant et la valeur après."],["Sans pre-authentification","Affaiblit l’authentification Kerberos. À n’activer qu’en cas de besoin avéré."],["Chiffrement DES","Chiffrement obsolète. À n’activer que pour une contrainte de compatibilité."],["Delegation approuvee","Autorise ce compte à agir au nom d’autres utilisateurs. À réserver aux comptes de service."],["Delegation contrainte","Autorise la delegation contrainte avec transition de protocole."],["Expiration","Date à laquelle le compte cesse de fonctionner."],["Fixer","Applique la date d’expiration choisie."],["Jamais","Retire toute date d’expiration du compte."],["Choisir l’OU de destination","Ouvre le sélecteur d’unités d’organisation du domaine : la destination se cherche, se choisit, puis se confirme. Aucun déplacement n’est lancé par ce clic."],["Groupe","Nom ou chemin complet du groupe."],["Ajouter","Ajoute ce compte au groupe indique."],["Retirer","Retire ce compte du groupe indique."]]},{"s":"Groupe","f":[["Nom du groupe","Nom du groupe chargé dans la fiche."],["Description","Description libre du groupe."],["Enregistrer","Enregistre les modifications du groupe."],["DN du membre à ajouter ou retirer","DN du membre à ajouter ou retirer."],["Ajouter membre","Ajoute le membre indique au groupe."],["Retirer membre","Retire le membre indique du groupe."],["Filtrer les membres","Filtre les membres affichés par nom, type, OU ou DN. Aucune requête AD : seuls les membres déjà lus sont filtrés."],["Membres",""],["Membres directs du groupe","Membres directs du groupe : nom, type (connu de la copie locale) et OU ; le DN complet est dans l’infobulle de la ligne. Clic droit pour rechercher l’objet ou copier son DN."]]},{"s":"Unité d’organisation","f":[["Unité d’organisation parente","Branche qui recevra la nouvelle unité d’organisation : celle sélectionnée dans l’arborescence, pas l’objet ouvert dans la fiche."],["Nom","Nom de la nouvelle unité d’organisation."],["Creer","Crée l’unité d’organisation sous la branche sélectionnée."]]},{"s":"Appartenances","f":[["Lire les groupes imbriqués","Lit, à la demande, les groupes dont ces groupes sont membres (2 000 groupes, 16 niveaux et 10 secondes au plus) et les ajoute à la liste comme appartenances imbriquées. Lecture seule ; aucun parcours du domaine."],["Filtrer les groupes","Filtre les groupes affichés par nom, OU, appartenance ou DN. Aucune requête AD : seuls les groupes déjà lus sont filtrés."],["Groupes",""],["Pourquoi membre","Réponse de « Pourquoi membre ? » : appartenance directe, chemin des groupes imbriqués lus, ou lecture incomplète. Le groupe principal n’est pas compris dans memberOf."],["Groupes de l’objet","Groupes dont cet objet est membre : nom, OU et appartenance (directe, ou imbriquée après « Groupes imbriqués ») ; le DN complet est dans l’infobulle de la ligne. Clic droit : rechercher, copier le DN, « Pourquoi membre ? »."]]},{"s":"Droits comparés","f":[["Second utilisateur","Identifiant court (sAMAccountName) ou DN du second utilisateur. Un identifiant est résolu dans la copie locale, sans requête AD ; un DN lance directement les lectures."],["Comparer les droits","Lit les groupes des deux utilisateurs en deux lectures bornées (2 000 groupes, 16 niveaux et 10 secondes au plus chacune). Aucune écriture, aucun parcours du domaine."],["Copier pour le ticket","Copie en texte brut le résultat affiché : groupes seulement chez l’un, seulement chez l’autre, communs, chemins et limites. Aucune donnée n’est relue."],["État de la comparaison","Saisissez le second utilisateur, puis lancez la comparaison. Le résultat indique les groupes propres à chaque compte, les groupes communs, le chemin d’appartenance et les limites de lecture."],["Groupes comparés","Groupes de chaque compte avec leur catégorie, le chemin d’appartenance et les groupes à privilèges. Le DN complet est dans l’infobulle de la ligne. Affichage local, aucune requête AD."]]},{"s":"Attributs","f":[["Nom de l’attribut Active Directory, par exemple description","Nom de l’attribut Active Directory, par exemple description."],["Nouvelle valeur","Nouvelle valeur. Pour vider l’attribut, utilisez Effacer attribut."],["Appliquer","Écrit la valeur indiquée dans l’attribut."],["Copier tout","Copie tous les attributs affiches."],["Effacer","Vide l’attribut indiqué."],["Attributs de l’objet","Attributs de l’objet. Clic droit pour copier un nom ou une valeur."]]},{"s":"Droits effectifs","f":[["Analyser","Analyse les droits de votre compte sur cet objet."],["Copier le rapport","Copie le rapport des droits."],["Sélectionnez un objet.",""],["Estimation par action","Estimation par action. Clic droit pour copier."]]}],"comptes":[{"s":"","f":[["Changer de compte","Ouvre la connexion sans fermer Domenia, préremplie avec le compte actuel : formulaire d’abord, session Windows proposée dessous. Annuler conserve la session en cours."],["Aucune identité active.",""],["Aucune connexion à l’annuaire.",""],["Mot de passe actuel du compte de connexion","Mot de passe actuel du compte de connexion, après son changement dans l’annuaire. Validé une seule fois à votre demande, jamais enregistré dans Domenia."],["Corriger le mot de passe","Valide ce mot de passe pour le même compte, une seule fois, puis l’applique sans reconnecter Domenia. Les lectures parties avec l’ancien mot de passe sont arrêtées ; aucune écriture n’est rejouée."],["Comptes utilisés en ce moment","Compte que chaque ressource prendra pour sa prochaine opération : annuaire, postes, LAPS et BitLocker, avec son origine et son état (refus enregistré, endroit où le corriger, autres noms confirmés par l’annuaire). Lecture seule ; aucun…"],["Comptes gardés en mémoire","Comptes gardés en mémoire pour cette session : compte poste saisi et comptes temporaires acceptés après un refus. Rien n’est enregistré sur le disque."],["Liste des comptes gardés en mémoire","Comptes gardés en mémoire, avec leur durée restante et leur état. « Oublier » retire le compte de la ligne ; une opération déjà envoyée garde sa copie et se termine."],["Effacer","Supprime le compte distant de la mémoire. DOMENIA réutilisera alors le compte AD courant."],["Repli sur le compte AD courant.",""],["Identifiant","Identifiant ayant les droits administrateur sur les postes."],["Mot de passe du compte poste","Mot de passe destiné au compte d’accès aux postes. Sa valeur n’est jamais lue ni affichée par l’aide contextuelle."],["Activer","Charge ce compte en mémoire pour les opérations distantes."],["Essayer sur le poste sélectionné","Lit une seule fois le système du poste ouvert dans Assistance poste (WMI, Win32_OperatingSystem), avec le compte utilisé pour les postes, pour vérifier le droit administrateur. Un seul poste, aucun relevé, aucun repli intrusif."],["Résultat de l’essai du compte poste","Résultat du dernier essai du compte poste : accès administrateur, accès refusé ou poste injoignable. Rien n’est enregistré."],["Mémoriser sur ce PC","Après validation, conserve ce mot de passe dans le coffre de votre profil Windows sur ce PC. Aucune copie dans la base Domenia."],["Utiliser le coffre","Lire ce compte dans le coffre Windows et lancer une seule validation à votre demande."],["Oublier le mot de passe","Supprimer du coffre Windows le mot de passe de l’identifiant affiché, pour cet usage."],["Identifiant mémorisé dans la base ; le mot de passe n’est jamais conservé.",""],["Mot de passe du compte secrets","Mot de passe destiné à la lecture des secrets AD. Sa valeur n’est jamais lue ni affichée par l’aide contextuelle."],["Tester","Teste l’authentification du compte contre le domaine."],["Annuaire : compte de connexion. Postes : compte poste saisi dans Assistance poste s’il existe, sinon compte Postes, sinon compte de connexion. Secrets : compte Secrets s’il existe, sinon compte de connexion. Les trois ressources sont indépendantes.",""],["Transports utilises","Transports utilisés par Domenia, leur état et leur règle. Aucun certificat accepté à l’aveugle, aucun réglage WinRM, pare-feu, antivirus ou stratégie modifié, aucun transport intrusif sans autorisation explicite et ciblée."],["Aucun transport intrusif sans autorisation explicite et ciblee.",""]]}],"relations":[{"s":"","f":[["Sélectionnez un utilisateur ou un poste depuis Rechercher.",""],["Aucune recherche complémentaire en cours.",""],["Précautions des relations","Affiche ou masque les précautions de la page et l’état de la détection du parc."],["Cache conservé ; détection uniquement sur demande.",""],["Vues des relations","Sépare la sélection des autres associations, des candidats et du diagnostic de recherche."]]},{"s":"Associations","f":[["Aucune sélection.",""],["Synthèse des associations","Affectation déclarée, dernière session observée et historique, chacun avec son origine et sa date. Une observation ne vaut pas affectation."],["Supprimer le lien sélectionné","Retire seulement le lien choisi dans l’onglet actif après confirmation, pas l’objet AD."],["Restaurer une association","Nomme et remet l’association supprimée localement le plus récemment, depuis le journal des relations. Inactif quand il n’y a rien à restaurer. Aucun objet Active Directory n’est lu ni modifié."],["Exporter les liens visibles","Exporte uniquement les liens de l’onglet Sélection ou Toutes les associations actuellement ouvert."],["Associations de la sélection","Associations enregistrées de l’utilisateur ou du poste sélectionné, avec leur qualification et leur date en heure locale."],["Sélectionnez d’abord un utilisateur ou un poste dans Rechercher. Ensuite choisissez Détecter ou Rechercher.",""],["Annuler","Annule la préparation de l’association. Aucun lien n’est ajouté."],["Confirmer l’association","Revérifie le poste dans Active Directory puis enregistre le lien local si la cible n’a pas changé."]]},{"s":"Associations › Détecter","f":[["Rechercher les postes","Cherche les postes connus et les indices AD du compte sélectionné. Aucune console n’est interrogée sans choix et confirmation explicites."],["Arrêter la recherche inverse","Demande l’arrêt de cette lecture. Une requête native déjà envoyée peut encore se terminer ; ses résultats ne sont pas appliqués après annulation."],["Ouvrir le poste candidat","Ouvre la fiche du poste AD identifié. Une simple adresse IP ne suffit pas."],["Déclarer l’association","Déclare volontairement un lien local après confirmation. Cela ne prouve pas une session active."],["Options de la recherche inverse","Révèle les choix de vérification des postes et des événements. Aucun accès n’est lancé à l’ouverture de cette section."],["Vérification réseau volontaire","Autorise, après confirmation au clic Rechercher, une lecture CIM/DCOM des consoles dans le périmètre choisi. Aucun script ou tâche n’est déposé."],["Périmètre des consoles","Choisissez les candidats connus, les machines des résultats chargés, ou l’OU choisie dans Rechercher. Le nombre et le temps restent bornés."],["Maximum de postes","Limite volontaire de 1 à 50 postes, par défaut 20. Atteindre la limite produit un résultat partiel."],["Indices d’authentification du contrôleur","Lit au plus 100 événements 4768 ciblés sur le SID du compte, sur le contrôleur courant. Les IP restent des indices non associés automatiquement."],["Sessions RDP","Option séparée, non disponible : la lecture porte sur la console. Une console vide ne prouve pas l’absence de session RDP."],["Périmètre de détection","Nombre de postes, périmètre demandé, limite et troncature. Zéro candidat signifie qu’aucune source n’en propose, pas que l’utilisateur n’a aucun poste."],["Annuler le périmètre","Abandonne ce périmètre. Aucun poste n’est contacté."],["Lancer la détection","Lit la console des seuls postes listés, dans la limite affichée. Compteurs interrogés, refusés, injoignables et restants pendant la lecture."],["Candidats de la recherche inverse","Liste progressive des indices et consoles de cette recherche. Les résultats partiels gardent leur nature et leur source."]]},{"s":"Associations › Rechercher","f":[["Nom du poste","Saisissez au moins deux caractères du nom ou du DNS du poste à associer."],["Rechercher","Recherche les postes dans tout le domaine sans modifier la recherche principale ni l’OU sélectionnée."],["Postes trouvés","Résultats Active Directory de la recherche manuelle. Sélectionnez une ligne avant de préparer l’association."],["Saisissez au moins deux caractères.",""],["Associer ce poste","Prépare l’association du poste sélectionné. La confirmation apparaît dans cette même page."]]},{"s":"Toutes les associations","f":[["Format de l’import","Format du fichier à importer : il fixe les colonnes lues et la source imposée aux associations (Import CSV, Import GLPI ou Import osquery)."],["Importer des associations","Lit le fichier au format choisi (CSV générique, export GLPI ou résultats osquery) et montre dans cette page les lignes valides, les conflits et les rejets avant tout ajout. La source imposée dépend du format ; l’import peut être annulé."],["Annuler l’import","Retire les associations du dernier lot d’import encore présentes, y compris après un redémarrage, après une confirmation dans la page qui en donne le nombre, le fichier et la date. Chaque retrait est journalisé ; « Restaurer » les remet…"],["Restaurer la suppression","Remet la dernière association retirée localement (suppression, annulation d’import ou orpheline), une par clic, depuis le journal. Le bouton nomme l’association. Aucun objet Active Directory n’est lu ni modifié."],["Associations orphelines","Vérifie en lecture seule que les comptes et postes des associations automatiques existent encore dans Active Directory, puis liste les orphelines dans la page avec leur motif. Rien n’est retiré sans confirmation."],["Exporter tout",""],["Filtrer les associations","Filtre la vue globale sur l’utilisateur, le poste, la source ou les détails. Aucune lecture réseau."],["Filtre Déclaré","N’affiche que les associations déclarées par un opérateur."],["Filtre Observé","N’affiche que les sessions observées sur les postes."],["Filtre Historique","N’afficher que les ouvertures de session anciennes relevées dans un journal ou un profil : un historique, pas une présence actuelle."],["Filtre Contradictoire","N’affiche que les postes où les sources désignent des comptes différents."],["Aperçu de l’import","Chaque enregistrement du fichier et ce que l’import en fera, avec sa catégorie : valide, conflit, rejet, doublon, déjà connue, inconnue dans l’index local ou reportée. Comptes et postes vérifiés sans accès réseau ; 64 associations au…"],["Importer les lignes retenues","Ajoute les lignes « À importer » au stockage local, chacune journalisée, avec la source imposée par le format choisi (Import CSV, Import GLPI ou Import osquery)."],["Abandonner l’import","Ferme l’aperçu sans rien ajouter."],["Retirer les orphelines cochées","Demande une confirmation dans le panneau, puis retire les associations cochées du stockage local. Chaque retrait est journalisé et restaurable."],["Fermer la liste des orphelines","Ferme la liste sans rien retirer."],["Annuler le retrait","Revient à la liste sans rien retirer."],["Confirmer le retrait","Retire les associations orphelines cochées du stockage local. Active Directory n’est pas modifié."],["Toutes les associations","Liens locaux du domaine courant, avec filtre et compteur. Double-clic : fiche de l’utilisateur ou du poste cliqué ; clic droit : ouvrir l’un ou l’autre."]]},{"s":"Détail","f":[["Méthodes essayées lors de la dernière recherche d’utilisateur","Méthodes essayées lors de la dernière recherche d’utilisateur, et leur résultat."]]}],"poste":[{"s":"","f":[["Aucun poste ouvert",""],["Rechercher un poste","Nom du poste. Entrée lance la recherche dans tout le domaine ; la saisie seule ne lit rien et ne sonde aucun poste."],["Derniers postes consultés","Postes ouverts récemment, gardés dans la mémoire locale de ce poste. Un clic recopie le nom ; Entrée lance la recherche."],["Aucun poste consulté récemment.",""],["Sélectionnez un objet dans Rechercher.",""],["Réessayer la lecture AD","Relit uniquement cette fiche AD, sans ping, sonde ni écriture."],["Présence non vérifiée",""],["Ouvrir la fiche de l’utilisateur associé","Ouvre la fiche de l’utilisateur associé à ce poste. Aucune écriture, aucune sonde du poste."],["aucun associé",""],["Aucun inventaire dans cette session",""],["Compte poste","Compte utilisé pour les opérations sur ce poste : C$, consoles, inventaire, diagnostic et sessions. Ouvre un panneau pour saisir un autre compte ou revenir au compte de connexion."],["Bureau à distance","Ouvre une connexion Bureau à distance vers ce poste avec le client Windows (mstsc)."],["Ouvrir le disque C (C$)","Ouvre le partage administratif C$ du poste dans l’Explorateur, avec le compte des opérations poste."],["Tester la réponse","Envoie un ping à ce poste et met à jour la pastille de présence. Aucune autre sonde."],["Vues d’assistance poste","Cinq vues du poste : vue d’ensemble, intervenir, détails, diagnostic et secrets. L’en-tête reste visible dans chacune."]]},{"s":"Vue d’ensemble","f":[["Nom du compte ordinateur","Nom du poste tel qu’il figure dans l’annuaire."],["Nom réseau complet","Nom DNS du poste utilisé par les opérations qui le prennent pour cible."],["Présence réseau","Dernier état de joignabilité connu. Un refus de réponse réseau ne prouve pas forcément que le poste est éteint."],["Système d’exploitation","Système déclaré dans la fiche AD du poste. Un inventaire distant peut fournir une information plus récente."],["Version du système","Version déclarée dans l’annuaire, pas nécessairement vérifiée en direct sur la machine."],["Description","Description libre du poste."],["Localisation","Emplacement physique du poste."],["Responsable","Nom du responsable du poste, lu dans l’annuaire. Le chemin complet reste interne : il ne se tape plus."],["Choisir le responsable","Ouvre le sélecteur d’utilisateurs du domaine : la recherche se lance sur Entrée ou sur le bouton, jamais pendant la frappe. Le choix reste local, aucune écriture n’est lancée par ce clic."],["Ouvrir le responsable","Ouvre la fiche de l’utilisateur choisi comme responsable du poste. Aucune écriture, aucune sonde de poste lancée par ce clic."],["Retirer le responsable","Retirer le responsable affiché de la fiche. L’effacement de la valeur dans l’annuaire ne se fait qu’à l’enregistrement."],["État du compte ordinateur","État du compte dans le domaine. Il ne décrit pas l’état de marche de Windows."],["Dernière connexion connue","Date retournée par l’annuaire pour le compte ordinateur, pas une mesure de présence instantanée."],["Options du compte ordinateur","Options techniques du compte AD. Lecture seule dans cette zone."],["Aucun utilisateur associé",""],["Ouvrir la fiche de l’utilisateur associé","Ouvre la fiche de l’utilisateur associé à ce poste. Aucune écriture, aucune sonde du poste."],["Détecter à nouveau l’utilisateur","Interroge ce poste pour connaître l’utilisateur connecté. Une association déjà enregistrée n’est pas remplacée."],["Utilisateur associé","Dernier utilisateur associé à ce poste."],["Origine de l’association","Source ayant fourni le lien utilisateur-poste : détection, import ou saisie, selon les données disponibles."],["Qualification de l’association","Badge de l’association (Declare, Observe, Importe, Indice) et règle qui le produit ; jamais un pourcentage ni une probabilité de session active."],["Date de l’association","Horodatage connu pour la détection ou l’enregistrement de cette association."],["Enregistrer","Enregistre les modifications de la fiche dans Active Directory."],["Modifier la fiche","Déverrouille la description et la localisation du poste. Le crayon n’écrit rien : il ouvre seulement la saisie, et « Enregistrer » reste seul à décider de ce qui part dans l’annuaire."],["Annuler les modifications","Rejette les modifications non enregistrées : chaque champ reprend la valeur lue dans l’annuaire et la fiche se verrouille de nouveau."],["État des modifications de la fiche","Dit ce que la fiche a en modification, et le signale quand une valeur non enregistrée a été abandonnée en changeant d’objet. Rien n’est parti sans que la page le dise."],["Activité de connexion du poste","Activité de connexion du compte ordinateur : date approximative répliquée (lastLogonTimestamp) et, après lecture, la date exacte connue de chaque contrôleur avec sa couverture."],["Lire la dernière connexion du poste sur chaque contrôleur","Lit, pour ce poste seulement, la date exacte de dernière connexion de son compte ordinateur (lastLogon) sur chaque contrôleur du domaine, avec la liste des contrôleurs lus et non lus. Lecture seule ; aucun contrôleur n’est plus…"],["Lancez un inventaire (rapide ou complet) : le tableau de bord se remplit avec ses résultats.",""],["Inventaire rapide pour le tableau de bord","Lit l’inventaire du poste (CIM) en environ 1 minute puis remplit ce tableau de bord."],["Inventaire complet pour le tableau de bord","Inventaire complet, plus long (environ 3 minutes) : ajoute les processus, les erreurs système, les tâches planifiées, les certificats et les connexions réseau."],["Avancement du relevé de ce poste","Avancement du relevé de ce poste. Le détail complet est écrit dans le journal."],["Arrêter le relevé de ce poste","Arrête le relevé de ce poste. Les mesures déjà reçues sont conservées ; rien n’est relancé."]]},{"s":"Intervenir","f":[["Autoriser une intervention sur ce poste pendant 5 minutes","Autorise pendant 5 minutes, pour ce poste seulement, les transports qui déposent un script, un service ou une tâche : « Exécuter un programme », replis PsExec ou tâche planifiée. Ne lance rien ; les droits restent obligatoires."],["Temps restant de l’intervention","Temps restant de l’autorisation d’intervention sur ce poste."],["Retirer l’autorisation d’intervention","Retire l’autorisation maintenant. Les sondes déjà envoyées peuvent finir ; aucune nouvelle intervention avec dépôt ne sera autorisée."],["Lire ce poste par tâche planifiée","À demander quand CIM ne répond pas : autorise une seule lecture de ce poste par PsExec ou tâche planifiée. Autorisation distincte de l’intervention, retirée après cette lecture."],["État des autorisations du poste","État des autorisations de ce poste : intervention de 5 minutes et lecture par tâche planifiée. Rien n’est autorisé sans votre clic."],["Bureau à distance","Ouvre une connexion Bureau à distance vers ce poste avec le client Windows (mstsc)."],["Ouvrir le disque C (C$)","Ouvre le partage administratif C$ du poste dans l’Explorateur, avec le compte des opérations poste."],["Gestion de l’ordinateur","Ouvre la console Gestion de l’ordinateur sur ce poste : services, journaux, disques et utilisateurs locaux."],["Observateur d’événements","Ouvre l’Observateur d’événements sur ce poste."],["Copier la commande PowerShell","Copie une commande Enter-PSSession pour ce poste. Avec un compte poste, elle le nomme : Windows demandera son mot de passe, jamais copié."],["Tester la réponse","Envoie un ping à ce poste et met à jour sa présence. Aucune autre sonde."],["Lancer le diagnostic","Ouvre la vue Diagnostic et lance ses contrôles en lecture seule : DNS, ports, partage, WinRM, WMI, espace disque et session."],["Actualiser les stratégies","Demande au poste d’appliquer de nouveau les stratégies de groupe (gpupdate /force), après une confirmation dans la page."],["Exécuter un programme","Prépare dans la page le lancement d’un programme sur ce poste : en arrière-plan sous le compte système, ou dans la session d’un utilisateur. Rien ne part avant « Lancer » et sa confirmation."],["Redémarrer le poste","Lit d’abord les sessions ouvertes du poste, puis propose un redémarrage différé avec message à l’utilisateur ou immédiat. Rien ne part avant votre confirmation."],["État du compte non lu.",""],["Activer le compte du poste","Réactive le compte du poste dans le domaine. Le changement se confirme dans la page avant l’envoi."],["Désactiver le compte du poste","Désactive le compte du poste dans le domaine : il ne pourra plus s’authentifier. Le changement se confirme dans la page avant l’envoi."],["Groupe","Nom ou chemin complet du groupe."],["Ajouter au groupe","Ajoute ce poste au groupe indiqué."],["Retirer du groupe","Retire ce poste du groupe indiqué."],["Nouveau nom","Nouveau nom du compte d’ordinateur dans l’annuaire."],["Renommer dans Active Directory","Renomme le compte d’ordinateur dans l’annuaire. Cette action ne renomme pas Windows sur le poste."],["Déplacer le poste dans une autre OU","Ouvre le sélecteur d’unités d’organisation pour ce poste : la destination se cherche, se choisit, puis se confirme. Le contrôleur revérifie le GUID du poste avant le déplacement ; aucun déplacement n’est lancé par ce clic."],["Lecture des sessions ouvertes…",""],["Redémarrer après un délai, avec message","Redémarrage différé : l’utilisateur voit le message et peut enregistrer son travail avant l’échéance. Choix par défaut."],["Message à l’utilisateur","Message affiché à l’utilisateur du poste, sur une ligne de 400 caractères au plus. Vide : message par défaut."],["Redémarrer maintenant","Redémarrage immédiat et forcé : le travail non enregistré sur le poste est perdu."],["Confirmer le redémarrage","Demande la confirmation dans la page, puis envoie le redémarrage au poste une seule fois. Jamais rejoué."],["Fermer le panneau de redémarrage","Ferme ce panneau sans rien envoyer au poste."],["Exécuter un programme sur le poste",""],["En arrière-plan (compte système)","Le programme tourne sous le compte système du poste, sans fenêtre visible. Pour un outil technique non interactif."],["Dans la session de l’utilisateur","Le programme s’ouvre dans la session déjà ouverte du compte indiqué ; il ne démarre pas si ce compte n’a pas de session."],["Compte de la session","Compte de la session ouverte sur le poste : DOMAINE\\identifiant. Prérempli avec l’utilisateur associé."],["Programme à lancer","Chemin du programme tel qu’il existe sur le poste, par exemple %SystemRoot%\\System32\\notepad.exe."],["Arguments du programme","Arguments passés au programme, sur une ligne. N’y saisissez aucun mot de passe : ils restent lisibles dans la tâche."],["Niveau d’exécution le plus élevé","Lance le programme avec les droits les plus élevés du compte choisi."],["Lancer le programme","Vérifie les champs puis demande la confirmation dans la page ; la tâche unique part une seule fois."],["Fermer le panneau d’exécution","Ferme ce panneau sans rien lancer."],["Lecture à la demande, distincte du dernier utilisateur connu. Un accès refusé ne signifie pas absence de session.",""],["Lire les sessions Windows","Interroge WTS sur la machine sélectionnée. Utilise le compte poste indiqué ; aucune déconnexion ni écriture distante."],["Sessions Windows","Sessions avec un compte. Les lignes sans compte (services, écran de connexion, écouteur RDP) sont masquées et comptées dans l’état. Double-clic sur une ligne : ouvrir la fiche du compte."],["Services non lus. « Lire les services » interroge ce poste en lecture seule.",""],["Lire les services du poste","Lit la liste des services de ce poste (Win32_Service) en lecture seule, sur ce clic uniquement."],["Automatiques arrêtés seulement","N’affiche que les services en démarrage automatique qui sont arrêtés. Filtre local, sans nouvelle lecture."],["Filtrer les services","Filtre local sur le nom ou le libellé du service, sans nouvelle lecture."],["Ouvrir les services dans la console","Ouvre Gestion de l’ordinateur sur ce poste : ses services y sont listés pour une action avancée."],["Services du poste","Services lus sur le poste, automatiques arrêtés en tête. Sélectionnez une ligne pour la démarrer ou la redémarrer."],["Démarrer le service sélectionné","Démarre le service sélectionné après une confirmation dans la page. Un service désactivé est refusé."],["Redémarrer le service sélectionné","Arrête puis redémarre le service sélectionné après une confirmation dans la page. Ce qu’il sert est interrompu un instant."]]},{"s":"Détails","f":[["Vues de détail du poste","Inventaire du poste ou logiciels installés."]]},{"s":"Détails › Inventaire","f":[["Inventaire rapide (≈1 min)","Matériel, système, disques, réseau, sécurité, correctifs, logiciels, services, comptes, partages et imprimantes."],["Inventaire complet (≈3 min)","Ajoute les processus, les tâches planifiées, les certificats, les connexions réseau et les erreurs récentes. Plus long."],["Copier","Copie l’inventaire et le détail par source."],["Exporter CSV","Enregistre l’inventaire et le détail par source au format CSV."],["Catégorie","N’affiche qu’une seule catégorie."],["Sélectionnez un poste, puis lancez l’inventaire.",""],["Éléments collectés","Éléments collectés. Clic droit pour copier une valeur."],["Détail par source","Ce qui a pu être lu, refusé ou reste indisponible sur ce poste."]]},{"s":"Détails › Logiciels","f":[["Charger les logiciels","Liste les logiciels installes pour tous les utilisateurs du poste."],["Par utilisateur","Ajoute les logiciels installés dans le profil des utilisateurs connectés."],["Applications Store","Ajoute les applications du Microsoft Store. Plus long."],["Mises à jour","Affiche aussi les correctifs et composants système, masqués par défaut."],["Copier","Copie la liste complete des logiciels."],["Exporter CSV","Enregistre la liste des logiciels au format CSV."],["Colonnes","Affiche les colonnes techniques : emplacement, commande de désinstallation, source. Masquées par défaut car elles débordent de l’écran."],["Affichage des logiciels","Choisit ce que l’onglet montre : la liste des logiciels, ou la synthèse en graphiques."],["Chargez les logiciels pour afficher la synthèse.",""],["Filtre","Cherche dans le nom, l’éditeur, la version ou l’emplacement."],["Portee","N’affiche que les logiciels installés pour tous, par utilisateur, ou du Store."],["Sélectionnez un poste, puis chargez la liste.",""],["Retirer le filtre","Retire le filtre appliqué à la liste."],["Logiciels détectés","Logiciels détectés. Clic droit pour copier un nom ou une commande de désinstallation."],["Aucune portée lue.",""],["Détail par portée","Ce qui a pu être lu pour chaque portée, ligne par ligne."]]},{"s":"Diagnostic","f":[["Vues de diagnostic du poste","Contrôles du poste ou, en profil Expert, explorateur WMI."]]},{"s":"Diagnostic › Contrôles","f":[["Lancer le diagnostic","Vérifie la résolution DNS, la joignabilité, les ports, SMB, WinRM, WMI, le système, l’espace disque et la session ouverte."],["Copier le rapport","Copie le rapport de diagnostic."],["Pret.",""],["Résultat de chaque contrôle","Résultat de chaque contrôle. Clic droit pour copier."]]},{"s":"Diagnostic › WMI","f":[["Charger","Liste root et ses espaces de noms WMI directs. Les classes sont ensuite chargées à la demande."],["Classes","Liste les classes de l’espace de noms sélectionné."],["Interroger","Affiche les valeurs de la classe sélectionnée sur ce poste."],["Copier","Copie les valeurs affichees."],["Exporter CSV","Enregistre les valeurs au format CSV."],["Filtre","Filtre facultatif. Exemple : DriveType=3."],["Limite","Nombre maximum de résultats."],["Sélectionnez un poste, puis chargez les espaces de noms.",""],["0 espace",""],["0 classe",""],["Propriétés de la classe","Propriétés définies par la classe et leur type."],["Instances","Valeurs lues sur le poste. Clic droit pour copier."]]},{"s":"Secrets","f":[["Lister les clés BitLocker","Liste les clés de récupération BitLocker de ce poste. Aucune clé n’est affichée sans votre demande."],["Lire le mot de passe LAPS","Lit le mot de passe administrateur local géré par LAPS. Il reste masqué jusqu’à votre demande."],["Afficher la valeur choisie","Affiche uniquement la valeur sélectionnée, brièvement. Les autres restent masquées."],["Copier","Copie la valeur sélectionnée. Le presse-papiers est effacé automatiquement après quelques instants."],["Copier tout","Copie groupée désactivée : une valeur à la fois."],["Vider","Efface les valeurs lues, conservées en mémoire."],["Sélectionnez un poste, puis listez les clés BitLocker ou lisez le mot de passe LAPS.",""],["Ouvrir le prerequis","Ouvre la page du prérequis manquant d’une lecture de secrets indisponible (Rechercher, Comptes, Fiabilité). Navigation seule : aucun droit ni réglage n’est modifié."],["Identifiant de récupération BitLocker","Saisissez les premiers caractères de l’identifiant affiché par le poste. Filtre local sur les métadonnées déjà lues : aucune clé n’est lue ni révélée."],["« Lister les clés BitLocker » affiche les métadonnées, sans aucune clé. Une seule clé est lue, à votre demande.",""],["Une valeur à la fois, affichée brièvement, jamais journalisée ni mise en cache.",""],["Identifiant de récupération de la clé affichée","Comparez cet identifiant à celui affiché par l’écran de récupération du poste avant de dicter la clé."],["Blocs de la clé de récupération","Les huit blocs de six chiffres, dans l’ordre où le poste les demande."],["Secondes restantes","Secondes restantes avant que la clé soit masquée."],["Prolonger 30 s","Prolonge une seule fois l’affichage de la clé de 30 secondes. Rien n’est relu ni copié."],["Masquer maintenant","Masque la clé tout de suite. Elle reste lisible à nouveau sur votre demande."],["Clés et mots de passe récupérés","Clés et mots de passe lus pour ce poste, masqués par défaut. Choisissez une ligne, puis affichez-la ou copiez-la avec les boutons ci-dessus : une valeur à la fois."]]}],"assistance":[{"s":"","f":[["Recette d’assistance","Choisissez le symptôme décrit par l’utilisateur. Le choix seul ne lit rien."],["Aucune sélection : ouvrez la fiche du compte ou du poste concerné.",""],["Choisissez une recette.",""],["Étapes de la recette","Étapes de la recette : ce qui est lu, pourquoi et à quel coût. Choisissez une étape, puis lancez-la."],["Lancer l’étape choisie","Ouvre la vue de l’étape puis lance sa seule lecture, pour l’objet sélectionné. Rien d’autre ne part."],["Ouvrir la vue de l’étape","Ouvre la vue où l’étape présente ses informations, sans rien lire."],["Choisissez une étape.",""]]},{"s":"Atelier support","f":[["Ouvre une fiche pour analyser ses données déjà chargées.",""],["Vider l'atelier","Efface uniquement les captures, repères et incidents en mémoire de l’atelier. Aucun effet sur Domenia.db ou AD."],["Étapes de l’Atelier","Choisissez l’analyse, la comparaison, les incidents, les repères ou la préparation d’un dossier."]]},{"s":"Atelier support › Comprendre","f":[["Recalculer la synthèse","Relit seulement les données déjà présentes en mémoire. Ne contacte pas AD."],["Epingler la fiche","Conserve un raccourci de session dans Reperes. Pas d'enregistrement sur disque."],["Vérifier les comptes","Ouvre les comptes utilisés pour l’annuaire, les postes et les secrets. Aucun test de connexion n’est lancé par ce raccourci."],["État du moteur","Affiche les tâches et informations de fonctionnement d’DOMENIA, sans lancer de sonde réseau."],["Aucune fiche chargee. Aucun diagnostic invente.",""],["Constats et vérifications","Sélectionnez un constat pour voir sa justification, sa source et la vérification proposée."],["Justification du constat","Détail du constat sélectionné. Une piste de vérification n’est pas une preuve de cause."]]},{"s":"Atelier support › Comparer A / B","f":[["Enregistrer la capture",""],["Charger une capture",""],["Fiche actuelle → A","Fige les valeurs déjà chargées en mémoire, sans lecture AD supplémentaire."],["Capturer la référence B","Enregistre en mémoire une copie de la fiche actuelle comme seconde référence de comparaison."],["Inverser A et B","Échange les deux références pour inverser le sens de lecture des différences."],["Effacer les captures","Retire A et B de l’Atelier. Ne supprime aucun objet ni aucune donnée de l’annuaire."],["Afficher seulement les écarts","Masque les valeurs identiques et conserve les différences ainsi que les informations indéterminées."],["A : aucune capture",""],["B : aucune capture",""],["Capturez A, actualisez ou ouvrez une autre fiche du même type, puis capturez B.",""],["Différences entre A et B","Sélectionnez une ligne pour lire les valeurs comparées. Une donnée non fournie reste indéterminée."],["Détail de la différence","Valeurs avant et après, ou différences entre les références. Les groupes affichés sont les groupes directs fournis."]]},{"s":"Atelier support › Incidents expliqués","f":[["Filtre litteral sur titre, code et zone","Filtre littéral sur titre, code et zone. Aucun motif regex ni requête réseau."],["Effacer la liste des incidents","Vide les incidents collectés dans l’Atelier. Le journal habituel d’DOMENIA n’est pas supprimé."],["Avertissements et erreurs de cette session, toutes cibles confondues. Aucun rattachement automatique a la fiche.",""],["Incidents de la session","Sélectionnez un incident pour lire le message et les pistes de vérification."],["Détail de l’incident","Détail local de l’incident sélectionné. Le message brut n’est pas inséré dans le dossier support exporté."]]},{"s":"Atelier support › Repères de session","f":[["Épingler cette fiche","Ajoute la fiche courante aux repères de session, dans la limite de 24 fiches."],["Ouvrir la fiche epinglee","Ouvre par le chemin AD memorise avec le moteur habituel. Peut declencher les lectures habituelles de la fiche."],["Retirer ce repère","Retire uniquement l’épingle sélectionnée. L’objet AD n’est pas supprimé."],["Fiches épinglées","Sélectionnez une fiche puis ouvrez-la. Une ouverture utilise les lectures habituelles d’Domenia."]]},{"s":"Atelier support › Dossier / ticket","f":[["Générer le dossier","Compose le dossier à partir de la fiche et des captures disponibles. Aucun envoi automatique."],["Copier le dossier","Génère le dossier puis le copie dans le presse-papiers. Les identifiants internes ne sont pas anonymisés."],["Enregistrer le dossier HTML","Exporte un dossier autonome vers le fichier choisi après confirmation. Relisez les informations internes avant partage."],["Ajouter l’incident sélectionné","Inclut les explications de l’incident choisi dans le dossier, pas son message brut."],["Aperçu du dossier","Texte du dossier avant copie ou export. Les champs dédiés aux secrets ne font pas partie du rapport."]]},{"s":"Atelier support › Dossier hors ligne","f":[["Périmètre du dossier","Périmètre du dossier : le poste sélectionné, les postes des résultats affichés (500 au plus) ou l’OU sélectionnée dans l’arborescence."],["Inclure les observations","Dernières observations enregistrées des postes (présence, console, inventaire, sondes), avec leurs dates."],["Inclure les associations","Associations utilisateur et poste mémorisées pour les postes du périmètre."],["Inclure les requêtes enregistrées","Définitions des requêtes enregistrées non archivées, avec leur empreinte."],["Préparer le dossier hors ligne","Écrit un nouveau dossier daté dans Exports pour le périmètre choisi. Aucune écriture dans la base, aucun accès réseau."],["Aucun dossier préparé dans cette session.",""]]}],"requetes":[{"s":"","f":[["Retour",""],["Choisir une OU",""],["Charger",""],["Nouvelle",""],["Aperçu local",""],["Choisissez un modèle, ou ajoutez des conditions.",""]]},{"s":"2. Aperçu","f":[["Retirer le segment",""],["Page précédente",""],["Page suivante",""],["Enregistrer ou réutiliser →",""],["Tout exporter (CSV)",""],["Objet sélectionné · fiche locale",""],["Sélectionnez un poste pour consulter ses données.",""],["Fiche AD et actions…",""],["Actualiser ce poste…",""],["Copier le chemin AD",""],["Répartition complète · toutes les valeurs",""],["Valeurs précédentes",""],["Valeurs suivantes",""],["Afficher ces postes",""]]},{"s":"1. Créer","f":[["Ajouter",""],["Parcourir le catalogue…",""],["Retirer la condition",""],["Collecter les données requises…",""],["Plan de collecte des informations manquantes",""],["Vérifier les informations disponibles",""],["Voir l’aperçu local →",""],["Conditions avancées et paramètres",""],["+ Groupe ET",""],["+ Groupe OU",""],["+ Groupe NON",""],["+ Critère choisi ci-dessus",""],["Retirer",""],["Effacer les groupes",""],["+ Collection",""],["+ Critère d’instance",""],["Paramétrer le critère sélectionné",""],["Fixer les valeurs actuelles",""],["Sélectionnez un paramètre pour saisir sa valeur.",""],["OU du tableau de bord",""],["Appliquer la valeur",""],["Revenir aux durées du profil",""],["Appliquer la fenêtre",""],["Couverture et dates des informations",""],["Vérifiez la couverture des informations avant l’aperçu.",""],["Appliquer la fenêtre proposée au brouillon",""]]},{"s":"WMI avancé","f":[["root\\cimv2",""],["Espaces enfants…",""],["Relire sur le poste plutôt que la base",""],["Classes de l’espace…",""],["Win32_OperatingSystem",""],["Lire le schéma…",""],["Préparer le SELECT avec les propriétés cochées",""],["SELECT Caption, Version FROM Win32_OperatingSystem",""],["100",""],["Exécuter sur le poste…",""],["Préparer une recette locale",""],["Aucune lecture WMI avancée lancée.",""],["Lire sur le poste…",""],["Lire cette relation…",""]]},{"s":"3. Enregistrer","f":[["Partager ou importer des recettes",""],["Bibliothèque Domenia",""],["Exporter ma bibliothèque (JSON)…",""],["Exporter cette requête (PowerShell)…",""],["Examiner un pack…",""],["L’import affiche les différences avant toute écriture. Les recettes ne lancent jamais de collecte implicitement.",""],["Choisir les nouvelles",""],["Appliquer mes choix…",""],["Restaurer avant cet import…",""],["Consultez l’aperçu pour vérifier les postes correspondants et les informations inconnues.",""],["Enregistrer",""],["Créer une sonde dashboard",""],["Archiver la requête",""],["Mettre à jour les éléments liés",""],["Garder l’ancienne version, enregistrer une copie",""],["Archiver et retirer les widgets",""],["Annuler",""],["Tester sur le poste sélectionné",""],["Appliquer aux résultats de Recherche",""],["Modifier les critères",""]]},{"s":"Bibliothèque","f":[["Page précédente",""],["Page suivante",""],["Sélectionnez une requête pour consulter son usage.",""],["Utiliser cette requête",""],["Restaurer la requête",""]]},{"s":"Informations","f":[["Utiliser cette information",""]]}],"audit":[{"s":"","f":[["Copier la vue affichée","Copie le résumé et les lignes de la vue affichée, pour un ticket. Aucune donnée n’est relue."],["Vues de l’audit AD","Objet sélectionné, contrôleurs du domaine ou identités d’une OU."]]},{"s":"Objet sélectionné","f":[["Reprendre la sélection","Prend l’objet de la fiche ouverte comme cible. Les résultats de la cible précédente sont effacés ; rien n’est lu."],["Aucun objet : ouvrez une fiche depuis Rechercher, puis revenez ici.",""],["Lectures de l’objet","Mot de passe, groupes, délégations, stratégies de groupe, identité du poste et associations."]]},{"s":"Objet sélectionné › Mot de passe","f":[["Lire la stratégie applicable","Lit la stratégie fine applicable (msDS-ResultantPSO), celle du domaine et l’échéance calculée par le contrôleur. Aucun mot de passe n’est lu."],["Lecture à la demande pour un compte utilisateur.",""],["Stratégie applicable","Éléments de la stratégie applicable, avec leur source et leur limite."]]},{"s":"Objet sélectionné › Groupes imbriqués","f":[["Lire les appartenances imbriquées","Parcourt les groupes de l’objet puis leurs propres groupes : 2 000 groupes, 16 niveaux et 10 secondes au plus."],["Lecture à la demande pour un utilisateur, un poste ou un groupe.",""],["Groupe à expliquer","Groupe à expliquer, choisi parmi ceux lus. Le choix calcule le chemin sans nouvelle lecture."],["Confirmer sur le contrôleur","Demande au contrôleur si l’objet est membre, directement ou par imbrication, du groupe choisi (une lecture LDAP)."],["Lisez d’abord les appartenances, puis choisissez un groupe.",""],["Groupes imbriqués lus","Groupes lus, avec la profondeur, le groupe par lequel l’appartenance arrive et l’état de lecture."]]},{"s":"Objet sélectionné › Délégations","f":[["Lire les délégations","Lit le propriétaire et la liste de contrôle d’accès de l’objet (1 000 entrées au plus), sans rien modifier."],["Entrées posées sur l’objet seulement","Masque les entrées héritées des conteneurs parents. Filtre local."],["Filtrer les délégations","Filtre local sur le bénéficiaire, les droits ou la cible."],["Lecture à la demande pour l’objet sélectionné.",""],["Inclure les groupes du bénéficiaire","Lit les groupes de sécurité du bénéficiaire choisi (tokenGroups) pour compter les entrées qui les désignent. Une lecture LDAP."],["Sélectionnez une entrée pour estimer les droits de son bénéficiaire.",""],["Estimation des droits","Résultat estimé par catégorie de droit, avec l’entrée qui le décide."],["Entrées de la liste de contrôle d’accès","Entrées observées : bénéficiaire, droits, cible et origine. Une entrée n’est pas un droit effectif."]]},{"s":"Objet sélectionné › Stratégies de groupe","f":[["Lire les liens GPO","Lit gPLink et gPOptions de chaque OU au-dessus de l’objet et du domaine, puis le nom des GPO. Liens de site non lus."],["Lire le résultat appliqué sur le poste","Lit par CIM le dernier résultat appliqué enregistré par le poste (RSoP). Droits d’administration du poste requis ; aucune actualisation des stratégies."],["Lecture à la demande pour un utilisateur, un poste ou une unité d’organisation.",""],["Constats des stratégies de groupe","Ce qui a été lu, ce qui ne l’a pas été et ce que cela ne prouve pas."],["Liens GPO et résultat appliqué","Une ligne par lien : lien, héritage et résultat sur le poste. Un lien ne prouve pas l’application."]]},{"s":"Objet sélectionné › Identité du poste","f":[["Vérifier l’identité du poste","Résout le nom DNS depuis ce poste, lit le nom inverse et interroge le poste par CIM (Win32_ComputerSystem). Aucune attribution ni fusion."],["Lecture à la demande pour un poste.",""],["Identité du poste","Identité vue par l’annuaire, par le DNS et par le poste, avec leur source."]]},{"s":"Objet sélectionné › Postes et utilisateurs","f":[["Sélectionnez un utilisateur ou un poste.",""],["Lire l’historique enregistré","Lit dans la base locale de ce poste les associations enregistrées pour ce sujet (200 lignes au plus). Aucune lecture réseau."],["Historique non lu.",""],["Historique enregistré des associations","Associations enregistrées, les plus récentes en premier, avec la nature de la preuve et son origine."]]},{"s":"Contrôleurs","f":[["Lister les contrôleurs","Lit les comptes des contrôleurs du domaine (100 au plus) et l’émulateur PDC. Aucune sonde réseau."],["Diagnostiquer les contrôleurs choisis","Pour 10 contrôleurs choisis au plus : DNS, ports LDAP et Kerberos, heure, synchronisation et réplication entrante. Sans droit d’administration."],["Lire les services des contrôleurs","Sonde privilégiée, sur demande seulement : état des services de l’annuaire des contrôleurs choisis, lu par CIM. Aucun service n’est démarré ni arrêté."],["Listez les contrôleurs, choisissez-en jusqu’à 10, puis lancez le diagnostic.",""],["Contrôleurs du domaine","Contrôleurs du domaine. Sélection multiple avec Ctrl ou Maj ; 10 au plus par diagnostic."],["Résultats du diagnostic des contrôleurs","Synthèse par contrôleur, liens de réplication et services."]]},{"s":"Contrôleurs › Synthèse","f":[["Constats du diagnostic","Enregistrements DNS et écarts calculés entre contrôleurs, avec leurs limites."],["Synthèse par contrôleur","Un contrôleur injoignable est « Non lu », jamais déclaré en panne."]]},{"s":"Contrôleurs › Réplication","f":[["Liens de réplication entrants","Liens de réplication entrants lus sur chaque contrôleur."]]},{"s":"Contrôleurs › Services","f":[["Services des contrôleurs","Services de l’annuaire des contrôleurs, comparés à l’état attendu."]]},{"s":"Identités","f":[["Périmètre : choisissez une OU dans l’arbre de Rechercher.",""],["Analyser les identités de l’OU","Lit les utilisateurs et postes de l’OU choisie (5 000 au plus), puis compare leurs noms avec la base locale de ce poste. Jamais le domaine entier."],["Inclure les sous-OU","Étend la lecture aux OU contenues dans l’OU choisie. Refusé à la racine du domaine."],["Analyse à la demande. Chaque constat est à revoir : rien n’est fusionné, renommé ni supprimé.",""],["Constats sur les identités","Constats à revoir, avec les objets concernés et la limite du constat."]]}],"schema":[{"s":"","f":[["Lire le schéma",""],["Schéma non lu dans cette session.",""],["Choisissez une classe ou un attribut.",""],["Analyser le filtre",""],["Ajouter l’attribut choisi",""],["Aucun filtre analysé.",""]]}],"synchro":[{"s":"","f":[["Relire l’OU choisie en entier",""],["Liste des objets manquants non lue.",""],["Lire les objets manquants…",""],["Actualiser la liste",""],["Vérifier les disparitions…",""],["Liste non lue.",""],["Enregistrer un relevé du périmètre",""],["Supprimer le relevé choisi…",""],["Aucun relevé lu.",""],["Comparer",""],["Choisissez deux relevés du même périmètre.",""]]}],"machine":[{"s":"","f":[["Fermer le panneau du compte poste","Ferme ce panneau sans changer le compte utilisé pour les postes."],["Compte utilisé pour les postes","Compte réellement utilisé pour la prochaine opération sur ce poste, et son origine. Aucun mot de passe n’est affiché."],["Compte poste","Compte administrateur des postes, sous la forme DOMAINE\\nom ou POSTE\\nom. Vide, Domenia garde le compte en service affiché au-dessus."],["Mot de passe du compte poste","Saisie protégée : l’aide contextuelle ne lit jamais la valeur de ce champ."],["Mot de passe affiché","Mot de passe affiché pendant 5 secondes, en lecture seule, sans copie possible."],["Afficher le mot de passe du compte poste pendant 5 secondes","Affiche le mot de passe du compte poste pendant 5 secondes, en lecture seule. Rien n’est copié ni enregistré."],["Utiliser ce compte pour les postes","Utilise ce compte pour les opérations sur les postes, en mémoire seulement. Il n’est jamais enregistré sur le disque."],["Revenir au compte de connexion","Oublie le compte saisi : les postes sont interrogés avec le compte Postes de la page Comptes s’il existe, sinon avec le compte de connexion ou votre session Windows."]]}],"operations":[{"s":"","f":[["Fermer le panneau des opérations","Ferme ce panneau. Les opérations continuent et restent comptées sur le bouton Opérations."],["Opérations à vérifier","Écritures envoyées qui attendent une vérification ou une revue, comptées comme sur la pastille de l’en-tête : les nouvelles écritures restent bloquées. Ferme ce panneau et ouvre la liste des reçus ; rien n’est rejoué."],["Opérations en cours","Opérations de cette session : en cours, en attente, arrêt demandé, à vérifier ou nettoyage. Arrêter agit sur une lecture de la ligne ; une ligne qui disparaît ne prouve pas un résultat."],["Dernières opérations","Opérations de cette session, la plus récente en haut : état, durée, étape la plus longue et référence à chercher dans Domenia.log. Gardées en mémoire seulement, 64 au plus."],["Étapes de l’opération choisie","Étapes mesurées de l’opération choisie et ce qui peut être fait ensuite. Aucune relance automatique."],["Copier le détail de l’opération","Copie le détail de l’opération choisie : étapes, durées et référence. Le nom de la cible peut y figurer : relisez avant envoi."],["Ouvrir le journal","Ferme ce panneau et ouvre le journal de session. Les références des opérations figurent aussi dans Domenia.log."],["Diagnostic expurgé","Prépare le diagnostic expurgé (versions, mesures locales, codes d’erreur, traces sans cible), le montre en entier, puis l’enregistre dans un fichier local après confirmation. Aucun envoi."],["Santé du moteur","Mesures locales de cette session : mémoire, réactivité de l’interface, temps de réponse par catégorie (recherche locale, interface, base locale, annuaire, postes, écritures et actions : médiane, 95e centile à partir de 20 mesures,…"]]},{"s":"Journal","f":[["Journal technique","Journal détaillé de l’application. Les noms internes ne sont pas anonymisés par la consultation ou la copie."]]}],"parametres":[{"s":"Fenêtre principale","f":[["Comptes","Ouvrir : Comptes."],["Outils","Ouvrir : Outils."],["Niveau de détail","Essentiel affiche les vues du quotidien. Expert ajoute les attributs, les permissions et WMI. Ce choix ne donne aucun droit supplémentaire ; aucun raccourci ne le change."],["Essentiel",""],["Expert",""],["Compte connecté","Compte et domaine utilisés pour l’annuaire. Le menu permet de changer de compte ou d’afficher « À propos » avec la version."],["Compte en préparation",""],["Domaine non connecté",""],["Compatibilité de ce poste","Compare ce poste à la matrice de compatibilité livrée : Windows, PowerShell, .NET et SQLite. Une fois évalué, le survol détaille chaque dimension. Lecture locale, sans réseau."],["Réduire ou déployer le menu","Replie le menu de gauche en icônes. Les rubriques, les aides au survol et la sélection restent accessibles. Cliquez à nouveau pour afficher les libellés."],["Accueil","Ouvrir : Accueil."],["Rechercher","Ouvrir : Rechercher."],["Fiche","Ouvre la fiche de l’objet sélectionné. Sans sélection, une page vide propose la recherche et les dernières fiches, sans rien lire sur le réseau."],["Poste","Ouvre les outils du poste sélectionné ; les actions attendent la lecture de sa fiche AD. Sans poste, une page vide propose la recherche et les derniers postes."],["Utilisateurs et postes","Ouvrir : Utilisateurs et postes."],["Atelier support","Ouvrir : Atelier support."],["{Binding Tag, RelativeSource={RelativeSource TemplatedParent}}",""],["Vider la recherche","Vide le champ de recherche. Les résultats affichés et l’OU restent inchangés."],["Palette de commandes","Ouvre la palette des actions disponibles. Raccourci Windows : Ctrl+K."],["Recherches et fiches récentes",""],["Suggestions","Recherches et fiches récentes (mémoire locale), puis objets de la base locale. Un clic recopie le texte ; seule Entrée interroge l’annuaire."],["Entrée lance la recherche dans l’annuaire ; les suggestions viennent de la mémoire et de la base locales.",""],["Où chercher","Partout : tout le domaine. Dans : l’OU choisie dans l’arbre de Rechercher, sous-OU incluses. Le choix ne lance aucune lecture."],["Dans l’OU choisie","Recherche limitée à l’OU choisie dans l’arbre de Rechercher et à ses sous-OU. Indisponible tant qu’aucune OU n’est choisie."],["OU de la recherche","Recherche limitée à l’OU choisie dans l’arbre de Rechercher et à ses sous-OU. Indisponible tant qu’aucune OU n’est choisie."],["Type cherché","Type cherché par la barre : tout, personnes, postes ou groupes. Le choix ne lance aucune lecture."],["Accès","Accès à revoir et comptes temporaires. Le badge indique les refus en attente. Aucun changement de compte sans votre accord, aucune écriture rejouée."],["Opérations","Affiche sous ce bouton les opérations en cours et en attente, leur durée, Arrêter par ligne et la santé du moteur. Aucun accès AD supplémentaire."],["Thème clair ou sombre","Bascule entre le thème clair et le thème sombre ; l’icône montre le thème obtenu. Clic droit : Clair, Sombre ou Automatique, qui suit le choix de Windows. Le choix est enregistré pour Domenia."],["Panneau d’aide","Affiche ou masque les explications à droite. Sur une fenêtre étroite, l’aide s’ouvre au-dessus du contenu ; cliquez de nouveau sur ? pour la fermer."],["Précédent","Revient à l’étape précédente (Alt+Gauche) : page, recherche, OU, sélection et défilement restitués depuis la mémoire, avec leur fraîcheur, sans nouvelle lecture ni sonde. Refusé tant qu’une saisie non enregistrée attend une décision."],["Suivant","Revient à l’étape suivante (Alt+Droite), sans nouvelle lecture ni sonde des postes."],["Session AD en préparation",""],["Désélectionner","Désélectionne l’objet affiché près du titre : sa fiche n’est plus montrée. Rien n’est modifié ni relu."],["Opérations à vérifier","Une écriture envoyée attend une vérification ou une revue : les nouvelles écritures restent bloquées. Ouvre la liste des reçus ; rien n’est rejoué."],["Repasser en lecture seule","Repasse tout de suite en lecture seule : les modifications AD et les actions distantes modificatrices sont de nouveau bloquées."],["Repasser en lecture",""],["Indicateur d’activité","Indicateur d’activité. Une animation sans pourcentage ne mesure pas la progression exacte."],["Annuler la lecture","Demande l’arrêt d’une lecture annulable. Une écriture ou un appel natif ne sont pas interrompus de force."],["Identités de connexion","Ouvre les identités de connexion utilisées par Domenia pour l’annuaire, les postes et les secrets."],["Protection des modifications","Lecture seule : les écritures AD et les actions distantes modificatrices sont bloquées. Un clic demande une confirmation dans la page avant d’autoriser les modifications ; la lecture seule revient seule après 15 min sans écriture…"],["Choisissez une rubrique dans la barre latérale","Choisissez une rubrique dans la barre latérale."],["Réduire le panneau d’aide","Masque la colonne de droite pour agrandir les résultats. Le bouton d’aide du bandeau permet de la rouvrir ; les infobulles restent actives."],["À quoi sert cet élément ?",""],["Survolez un contrôle ou utilisez Tab pour lire son rôle ici. Les champs de mot de passe ne sont jamais recopiés dans cette aide.",""],["Chapitre du guide","Chapitre du guide qui décrit la page affichée."],["Ouvrir le guide","Ouvre le guide PDF placé dans le dossier DOC à côté de Domenia ; le chapitre de la page est indiqué au-dessus. Aucun accès réseau."],["Aucune fiche ouverte",""],["Comptes utilisés","Affiche seulement les noms des identités configurées. Une identité active ne confirme pas ses droits sur une cible."],["Ouvrir les comptes","Vérifier quel compte est utilisé pour chaque ressource."],["1. Trouver","Ouvre la recherche. Aucun scan n’est lancé par ce raccourci."],["2. Consulter","Ouvre la fiche déjà chargée. Sélectionnez d’abord un objet dans la recherche ou dans l’annuaire."],["3. Préparer","Ouvre l’Atelier pour comparer des captures ou préparer un dossier. Ce n’est pas une étape d’exécution automatique."],["Dernier message du journal","Dernier message de la session. Un clic sur la barre déplie le journal."],["1 erreur",""],["Suivre","Désactivez pour lire le journal sans défilement automatique."],["État du moteur","Ouvre le panneau des opérations : tâches en cours et santé du moteur (mémoire, réactivité de l’interface, dernière sauvegarde). Aucune sonde réseau."],["Copier","Copie le journal tel qu’il est affiché. Cochez Masquer les noms pour remplacer chemins AD, comptes, noms DNS et adresses."],["Masquer les noms à la copie","Copier remplace les chemins AD, comptes, noms DNS et adresses par des repères. Un nom de poste isolé peut rester visible : relisez avant envoi."],["Effacer","Efface seulement le journal affiché."],["Taille du journal","Déplie ou replie le journal de session. Replié, il montre la dernière ligne et une pastille rouge pour une erreur non lue. L’enregistrement continue dans les deux cas."],["Journal de session","Événements et erreurs de la session. Désactivez Suivre pour lire sans défilement automatique. Copier masque les noms internes si Masquer les noms est coché."],["Journal de session lisible","Heure, niveau et message de la session. Le format brut et l’état du moteur sont dans le profil Expert."],["Rechercher dans le journal","Recherche littérale dans le journal actuellement affiché. Entrée ou Suivant parcourt les occurrences sans requête réseau."],["Occurrence suivante","Sélectionne la prochaine occurrence et met le défilement automatique en pause. L’enregistrement du journal continue."],["Erreurs seulement","N’affiche que les erreurs du journal lisible. L’enregistrement continue pour tous les niveaux."],["Retour à la ligne du journal","Replie les longues lignes pour les lire sans déplacement horizontal. Ne modifie pas les événements enregistrés."],["Taille du texte du journal","Ajuste uniquement la taille de lecture, entre 10 et 18. Le choix est mémorisé."],["Densité des résultats","Réglage d’affichage : Confort, lignes de 36 unités ; Compact, lignes de 28 unités. Mémorisé. Ne change ni les filtres AD ni vos droits."],["Réduire le zoom","Réduire l’interface de 10 %"],["Réinitialiser le zoom à 100 %","Revenir à 100 %"],["Agrandir le zoom","Agrandir l’interface de 10 %"]]},{"s":"Outils","f":[["Aucune OU racine : le domaine entier reste le défaut.",""],["Choisir",""],["Revenir au domaine",""],["Outils de l’application","Choisissez un outil de vérification ou de gestion locale. Certaines vues sont disponibles en mode Expert."]]},{"s":"Fiabilité","f":[["Lecture des reçus locaux en attente. Les écritures restent protégées.",""],["Actualiser les reçus","Lit les reçus locaux sans rejouer aucune opération."],["Reçus des opérations","Reçus des écritures envoyées par Domenia, ceux à vérifier en premier. Survolez l’objet pour lire son nom distinctif."],["Reçu sélectionné","Ce que dit le reçu sélectionné et ce que vous pouvez en faire."],["Motif de la revue","Décrivez le contrôle réalisé avec un autre outil, en 12 à 240 caractères. Le motif est enregistré dans le reçu : n’y saisissez ni mot de passe ni clé."],["Longueur du motif","Longueur du motif saisi : 12 caractères au minimum, 240 au maximum."],["Vérifier par relecture","Relit sur le contrôleur initial les valeurs attendues d’une modification de fiche. Aucune commande n’est renvoyée."],["Consigner la revue","Enregistre dans le reçu le motif saisi, après votre contrôle réel. Le reçu devient « Revue manuelle », pas un succès automatique."],["Aucune modification de formulaire en attente.",""],["Comparer les saisies","Compare les champs modifiés avec la première lecture et une éventuelle réponse plus récente. Aucun remplacement automatique."],["Les sondes ordinaires ne créent ni service ni tâche. Les anciens transports avec dépôts demandent une autorisation distincte.",""],["Une lecture ne bascule jamais seule sur PsExec ou une tâche planifiée. Demandez-le pour la lecture qui en a besoin.",""],["Autoriser une intervention sur cette machine","Autorisation de cinq minutes, pour la machine sélectionnée uniquement. Ne lance rien ; les droits restent obligatoires."],["Lire ce poste par tache planifiee","A demander quand CIM ne répond pas : autorise une seule lecture par PsExec ou tâche planifiée, pour la machine sélectionnée."],["Retirer l'autorisation","Les sondes déjà envoyées peuvent encore finir. Aucune nouvelle intervention avec dépôt ne sera autorisée."],["Diagnostic expurgé","Prépare le diagnostic expurgé (versions, mesures locales, codes d’erreur, traces sans cible), le montre en entier, puis l’enregistre dans un fichier local après confirmation. Aucun envoi."],["Pourquoi une action est indisponible ?","Explique les protections et preconditions actuelles sans modifier de droit."],["Revérifier le périmètre consulté en arrière-plan","Relit la dernière requête explicite, au plus toutes les trois minutes et dans sa limite de résultats. Aucun scan au démarrage."],["Les mesures locales apparaîtront ici.",""],["Ouvrir Pesto","Exécutable configuré et contrôlé par empreinte. Aucun identifiant ou ordre d'intervention transmis."],["Ouvrir FilPro","Exécutable configuré et contrôlé par empreinte. Aucun identifiant ou ordre d'intervention transmis."]]},{"s":"Vérification","f":[["Vérification rapide","Contrôles essentiels de la connexion et des composants."],["Vérification complète","Contrôles complets avec mesures de performance. Plus long."],["Copier le rapport","Copie le rapport de vérification."],["Exporter le diagnostic","Enregistre un dossier de diagnostic à joindre à une demande de support."],["Check rapide automatique en attente.",""],["Résultat de chaque contrôle","Résultat de chaque contrôle. Clic droit pour copier."]]},{"s":"Base autonome","f":[["Choisir l’OU de mise à jour","Choisit précisément l’OU et ses sous-OU à relire. Recherche n’est pas modifiée."],["Choisissez une OU",""]]},{"s":"Base autonome › Mise à jour","f":[["Tout relire dans l’OU choisie","Action recommandée : relit tous les utilisateurs et postes de l’OU choisie et de ses sous-OU. Demande une sélection si aucune OU n’est choisie. Les autres branches sont conservées. Une sauvegarde vérifiée de la base précède la lecture."],["Comptes de la base locale","Comptes utilisateurs enregistrés dans la base locale de ce domaine."],["Précision sur les comptes","Nature des objets comptés dans la tuile Comptes."],["Postes de la base locale","Postes (objets ordinateur) enregistrés dans la base locale de ce domaine."],["Postes actifs et désactivés","Postes actifs et désactivés dans Active Directory, selon la dernière lecture enregistrée."],["Associations de la base locale","Associations utilisateur-poste conservées dans la base locale."],["Précision sur les associations","Nature des liens comptés dans la tuile Associations."],["Âge de la dernière mise à jour","Âge de la dernière lecture complète couvrant le périmètre choisi."],["Date de la dernière mise à jour","Date et heure de la dernière lecture complète couvrant le périmètre choisi."],["Détection manuelle","Ancien reglage desactive : aucun releve collectif au lancement. Utiliser les actions de Rechercher ou Associations."],["Lire le journal du controleur","Une seule requête sur le contrôleur rend des milliers de couples utilisateur et poste, sans contacter aucune machine."],["Oublier les relevés","Efface l’état du parc dans la base locale, après confirmation et une sauvegarde vérifiée. Le prochain relevé repartira de zéro ; les associations sont conservées."],["Aucun relevé.",""]]},{"s":"Base autonome › Données","f":[["Rechercher","Cherche dans les noms, identifiants, descriptions et services. Les fautes de frappe sont rattrapees automatiquement."],["Prêt.",""],["Afficher / actualiser les objets",""],["Page précédente",""],["Page suivante",""],["Tri par pertinence","Rétablit le tri par pertinence puis nom sur tous les résultats."],["Ouvrir l’objet","Recherche dans l’annuaire l’objet sélectionné ci-dessous."],["Exporter CSV","Enregistre les résultats affichés au format CSV."],["Résultats de l’index local","Résultats de l’index local. Double-clic pour ouvrir l’objet dans l’annuaire."]]},{"s":"Base autonome › Stockage","f":[["Emplacement de la base","Base autonome de ce domaine : taille et dernière sauvegarde. Le chemin complet du fichier s’affiche dans cette infobulle dès que la base est ouverte."],["Copier le chemin de la base","Copie le chemin complet du fichier de la base dans le presse-papiers."],["Ouvrir l’emplacement de la base","Ouvre le dossier de la base dans l’explorateur, fichier sélectionné."],["Sauvegarder la base maintenant","Copie cohérente de la base (sauvegarde SQLite à chaud) dans son dossier Backups. L’original n’est pas modifié."],["Copier une sauvegarde de la base","Sauvegarde la base puis copie cette sauvegarde vérifiée vers le fichier de votre choix (clé USB, partage…)."],["Déplacer la base locale","Déplace la base vers un nouveau fichier local : vérification de la destination, copie contrôlée puis bascule. L’original est conservé en lecture seule."],["Restaurer une sauvegarde","Restaure une sauvegarde vérifiée dans un nouveau fichier local, après aperçu du domaine, des dates et du contenu. Aucune base n’est écrasée."],["Reprendre la bascule","Reprend une bascule interrompue après vérification de la copie. Les deux fichiers sont conservés."],["Revenir à la base précédente","Revient au fichier d’origine si la nouvelle base n’a reçu aucune écriture. Les deux fichiers sont conservés."],["Assistant de stockage","Étape et résultat de l’assistant de déplacement ou de restauration de la base."],["Espace disque de la base","Espace libre mesuré du volume de la base, seuil de suspension des collectes et données encore en mémoire."],["Reprendre les sauvegardes","Relance l’enregistrement des lots restés en mémoire après un échec du stockage local. Aucune écriture dans l’annuaire."],["Reprendre les anciennes données","Vérifie le domaine et les anciens fichiers, affiche la simulation dans la page, puis demande confirmation avant sauvegarde et import."],["La simulation des anciennes données sera affichée ici avant confirmation.",""],["Sauvegarde automatique","Sauvegarde cohérente automatique, contrôlée par SQLite et par empreinte, tant que Domenia est ouvert. Enregistrez les réglages pour l’appliquer."],["Intervalle des sauvegardes","Intervalle entre deux sauvegardes automatiques, de 1 à 720 heures."],["Sauvegardes à conserver","Nombre de sauvegardes gardées dans le dossier Backups, de 2 à 30 ; les plus anciennes sont retirées."],["État des sauvegardes","Fréquence, prochaine sauvegarde, dernier succès vérifié et dernier échec de cette session."],["Conservation : Présence ping","Âge au-delà duquel le dernier relevé de présence ping d’un poste peut être retiré. 0 conserve sans limite."],["Conservation : Utilisateur connecté","Âge au-delà duquel le dernier utilisateur connecté relevé peut être retiré. 0 conserve sans limite."],["Conservation : Inventaire","Âge au-delà duquel le dernier inventaire léger d’un poste peut être retiré. 0 conserve sans limite."],["Conservation : Sondes","Âge au-delà duquel les résultats de sondes WMI peuvent être retirés. 0 conserve sans limite."],["Conservation : Détails","Âge au-delà duquel les résultats détaillés peuvent être retirés. 0 conserve sans limite."],["Conservation : historique des associations","Âge au-delà duquel les observations identiques répétées de l’historique des associations sont résumées ; chaque changement d’utilisateur est gardé. 0 conserve tout."],["Enregistrer les réglages de stockage","Enregistre la fréquence des sauvegardes et la conservation par famille. Rien n’est supprimé à l’enregistrement."],["Prévisualiser la conservation","Compte, sans rien supprimer, ce que la conservation retirerait par famille, et annonce la perte de détail."],["Appliquer la conservation","Après la prévisualisation : sauvegarde vérifiée de la base, puis retrait des données annoncées. Confirmation demandée."],["Résultat de la conservation","Résultat de la prévisualisation ou de l’application de la conservation, famille par famille."],["Politique des données locales","Déplie ce que Domenia garde sur ce poste : contenu, emplacement, conservation, export et suppression de chaque donnée. L’ouverture relit seulement les réglages locaux ; rien n’est envoyé hors du poste."],["Engagement sur les données locales","Engagement de Domenia : aucune télémétrie ni service en ligne. Les lectures visent seulement l’annuaire, les postes et les serveurs internes que vous désignez."],["Données locales de Domenia","Ce que Domenia garde sur ce poste : contenu, emplacement, durée de conservation, export et suppression. Lecture seule ; rien n’est envoyé hors du poste."],["Stockage local",""],["Mesurer le stockage local","Compte les lignes et mesure la base active en lecture seule. Les tailles indisponibles restent inconnues. Aucune suppression, aucun contact avec les postes ou l’annuaire."],["Aucune mesure pour cette session.",""],["Contrôler l’intégrité de la base","Contrôle la base en lecture seule : schéma, tables, identité, reçus, structure SQLite et journal. Aucune réparation automatique."],["Contrôle d’intégrité","Résultat du dernier contrôle d’intégrité de cette session."],["Limites du stockage local","Limites explicites de mémoire, de disque et de conservation du stockage local."],["Purger les observations","Données reconstructibles ; associations conservées."],["Purger les instantanés","Résultats déjà lus ; aucune suppression dans AD."],["Purger l’index local","La prochaine mise à jour explicite reconstruira l’index. Le domaine reste identifié."],["Purger l’historique ancien","Conserve les associations déclarées et leur historique, ainsi que les dates illisibles."],["Âge minimal en jours","De 1 à 36500 jours."],["Simuler la purge","Compte les lignes choisies dans la base locale. Aucune suppression ; attend la fin des opérations en cours."],["Purger les données locales","Demande confirmation après simulation. Associations, historique protégé, secrets, configuration, journaux et reçus sont conservés. Aucun rejeu automatique."],["Choisissez les données à oublier puis simulez.",""]]},{"s":"Charge & stats","f":[["Actualiser","Relit les statistiques depuis Domenia.db."],["Exporter CSV","Exporte les statistiques agregees dans le dossier data\\Exports."],["Aucune mesure chargee.",""],["Statistiques des opérations","Consultez les opérations récapitulées par Domenia. Le tableau n’exécute aucune action sur un poste."]]},{"s":"Relevés","f":[["Aucun relevé en cours.",""],["Arrêter",""],["Aucun relevé interrompu.",""],["Reprendre",""],["Abandonner",""],["Actualiser la liste",""]]},{"s":"Domaine","f":[["Analyser le domaine","Lit l’état du domaine et de ses contrôleurs."],["Copier le rapport","Copie le rapport sur le domaine."],["Totaux de la copie locale","Totaux de la copie locale (base autonome) et date de sa dernière synchronisation. Aucun dénombrement n’est lancé sur l’annuaire."],["Pret.",""],["Informations relevées","Informations relevées. Clic droit pour copier."]]},{"s":"Commandes","f":[["Charger les commandes","Liste les commandes disponibles sur ce poste."],["Cherche par nom de commande, module ou paramètre","Cherche par nom de commande, module ou paramètre."],["N’affiche que les commandes d’un module","N’affiche que les commandes d’un module."],["Effacer le filtre","Efface le filtre et affiche toutes les commandes."],["0 commande",""],["Commandes disponibles","Commandes disponibles. Clic droit pour copier."],["Copier la commande","Copie le nom de la commande."],["Copier la syntaxe","Copie la syntaxe de la commande."],["Copier l’aide","Copie l’aide complète de la commande."],["Description, syntaxe, paramètres et exemples de la commande sélectionnée","Description, syntaxe, paramètres et exemples de la commande sélectionnée."]]},{"s":"Palette de commandes","f":[["Fermer la palette","Ferme la palette sans rien lancer. Échap fait de même."],["Rechercher une action","Tapez quelques lettres : accents et majuscules sont ignorés. Flèches pour choisir, Entrée pour exécuter, Échap pour fermer."],["Actions","Actions de la palette : les disponibles d’abord, avec leur raccourci. Une action indisponible dit pourquoi."],["Détail de l’action choisie","Ce que fait l’action choisie, ou pourquoi elle est indisponible."],["État de la palette","Nombre d’actions affichées et touches utiles : Entrée exécute, Échap ferme, Ctrl+K rouvre la palette."]]},{"s":"Confirmations en ligne","f":[["Détails techniques",""],["Réponse sûre","Retire la demande sans rien modifier (Échap)."],["Confirmer la demande","Exécute l’action décrite, une seule fois. Une demande d’une session précédente n’exécute rien."]]}]};
